<?php
namespace App\Domain\BulkImport\Services;
use App\Domain\BulkImport\Enums\MigrationItemStatus;use App\Models\{District,Document,DocumentType,MigrationBatchItem,RevenueCircle};
class MigrationItemValidator{public function validate(MigrationBatchItem $item):void{$p=$item->source_payload;$errors=[];$warnings=[];$type=DocumentType::where('code',trim((string)($p['document_type_code']??'')))->where('is_active',true)->first();$district=District::where('code',trim((string)($p['district_code']??'')))->where('is_active',true)->first();$circle=RevenueCircle::where('code',trim((string)($p['revenue_circle_code']??'')))->where('is_active',true)->first();if(!$type)$errors[]='UNKNOWN_DOCUMENT_TYPE';if(!$district)$errors[]='UNKNOWN_DISTRICT';if(!$circle)$errors[]='UNKNOWN_REVENUE_CIRCLE';if($district&&$circle&&$circle->district_id!==$district->id)$errors[]='CIRCLE_DISTRICT_MISMATCH';if(trim((string)($p['title']??''))==='')$errors[]='TITLE_REQUIRED';$year=trim((string)($p['record_year']??''));if($year!==''&&(!ctype_digit($year)||(int)$year<1700||(int)$year>(int)now()->year))$errors[]='INVALID_RECORD_YEAR';if(!$errors&&$type&&$district&&$circle){$duplicate=Document::where('document_type_id',$type->id)->where('district_id',$district->id)->where('revenue_circle_id',$circle->id)->when($p['patta_no']??null,fn($q,$v)=>$q->where('patta_no',trim($v)))->when($p['dag_no']??null,fn($q,$v)=>$q->where('dag_no',trim($v)))->when($year,fn($q,$v)=>$q->where('record_year',(int)$v))->exists();if($duplicate)$warnings[]='POTENTIAL_DUPLICATE';}$normalized=$errors?null:['document_category_id'=>$type->document_category_id,'document_type_id'=>$type->id,'district_id'=>$district->id,'revenue_circle_id'=>$circle->id,'title'=>trim((string)$p['title']),'patta_no'=>$this->nullable($p['patta_no']??null),'dag_no'=>$this->nullable($p['dag_no']??null),'record_year'=>$year!==''?(int)$year:null,'landholder_name'=>$this->nullable($p['landholder_name']??null),'guardian_name'=>$this->nullable($p['guardian_name']??null),'physical_file_reference'=>$this->nullable($p['physical_file_reference']??null),'remarks'=>'Imported from migration batch '.$item->migration_batch_id];$status=$errors?MigrationItemStatus::Invalid:($warnings?MigrationItemStatus::Warning:MigrationItemStatus::Valid);$item->update(['normalized_payload'=>$normalized,'errors'=>$errors?:null,'warnings'=>$warnings?:null,'status'=>$status]);}private function nullable($v):?string{$v=trim((string)$v);return $v===''?null:$v;}}
